import { readFileSync, writeFileSync, readdirSync } from "node:fs";

const note = `In a monorepo, \`README.md\`, \`llms.txt\`, \`docs/\`, \`design.md\`, and \`package.json\` may also exist per workspace member (\`apps/*\`, \`packages/*\`, …). When working inside a member, apply the steps above at both levels — the member's own copies govern that member's code and take precedence over the root copies; the root copies govern repo-wide concerns.

`;

for (const f of readdirSync("rules").filter((n) => n.endsWith(".md"))) {
  const path = `rules/${f}`;
  let raw = readFileSync(path, "utf8");
  if (!raw.includes("## 1. Core Principles")) throw new Error(`${path}: anchor not found`);
  raw = raw.replace(/(?=## 1\. Core Principles)/, note);
  writeFileSync(path, raw);
  console.log(`✓ ${path}`);
}
EOF
